define('Newsletter.Form.View', [
    'SC.Configuration',
    'ReCaptcha',
    'newsletter_form.tpl',
    'Newsletter.View',
    'Newsletter.Model.Site',
    'Backbone.CompositeView',
    'Backbone.FormView',
    'jQuery',
    'Tracker',
    'underscore'
], function NewsletterFormView(
    Configuration,
    Recaptcha,
    newsletterFormTpl,
    NewsletterView,
    NewsletterModelSite,
    BackboneCompositeView,
    BackboneFormView,
    jQuery,
    Tracker,
    _
) {
    'use strict';

    return NewsletterView.extend({
        template: newsletterFormTpl,
        initialize: function initialize(options) {
            var self = this;
            this.model = new NewsletterModelSite();
            this.state = {
                code: '',
                message: '',
                messageType: ''
            };

            this.application = options.application;

            this.recaptcha = new Recaptcha({
                configKey: 'n'
            });
            this.options.application.getLayout().once('afterAppendView', function afterAppendToDom() {
                self.setRecaptchaInForm();
            });

            this.email = options.email || null;

            if (this.email) {
                this.model.set('email', this.email);
            }

            BackboneCompositeView.add(this);
            BackboneFormView.add(this, options);

            this.model.on('saveCompleted', function saveCompleted() {
                Tracker.getInstance().trackEvent({
                    category: 'newsletter-signup',
                    action: 'click',
                    value: 1,
                    callback: _.noop(),
                    user: self.model
                });
                self.clearValues();
                self.state.code = 'OK';
                self.state.message = _('Thank you! Welcome to our newsletter').translate();
                self.state.messageType = 'success';
                self.render();
                self.setRecaptchaInForm();
            });
        },

        setRecaptchaInForm: function setRecaptchaInForm() {
            var $placeholder = this.$el ? this.$el.find('.newslleter-page-email-profile-recaptcha') : null;
            if ($placeholder) {
                this.recaptcha.attachTo($placeholder[0]);
            }
        },

        clearValues: function clearValues() {
            this.model.set('firstname', '');
            this.model.set('lastname', '');
            this.model.set('email', '');
            this.model.set('zipcode', '');
            this.model.set('birth', '');
        },

        bindings: {
            '[name="firstname"]': 'firstname',
            '[name="lastname"]': 'lastname',
            '[name="email"]': 'email',
            '[name="birth"]': 'birth'
        },

        events: {
            'submit form': 'submitForm'
        },

        validateCaptcha: function validateCaptcha() {
            var promise = jQuery.Deferred();
            this.recaptcha.validate(function onSuccess() {
                promise.resolve();
            }, function onError(e) {
                console.log(e);
                promise.reject(e);
            });
            return promise;
        },

        submitForm: function submitForm(e, model, props) {
            var self = this;
            e.preventDefault();
            return this.validateCaptcha().then(function then() {
                return self.saveForm(e, model, props);
            });
        },

        getBreadcrumbPages: function getBreadcrumbPages() {
            return [{
                href: '#',
                text: _('Email Sign Up').translate()
            }];
        },
        getContext: function getContext() {
            var config = Configuration.newsletter;
            return {
                isFeedback: !!this.state.code,
                model: this.model,
                disclaimer: config ? config.lightboxDisclaimer : '',
                terms: config ? config.termsMessage : ''
            };
        }
    });
});

define('Newsletter.Lightbox', [
    'SC.Configuration',
    'Newsletter.Model.Site',
    'Newsletter.Lightbox.View',
    'Utils',
    'underscore',
    'js.cookie'
], function NewsletterLightbox(
    Configuration,
    NewsletterModelSite,
    NewsletterLightboxView,
    Utils,
    _,
    Cookies
) {
    'use strict';

    var clearTime = function clearTime(time) {
        return clearTimeout(time);
    };

    var openNewsletterModal = function openNewsletterModal(application, e) {
        var view = new NewsletterLightboxView({
            model: new NewsletterModelSite(),
            application: application
        });
        e.preventDefault();
        view.showInModal();
    };

    return {
        loadModule: function loadModule(application) {
            var layoutComponent = application.getComponent('Layout');
            var domain = '.' + Utils.getWindow().location.hostname;
            var time;
            var config = Configuration.newsletter;
            var delay = 60000;

            if (config.lightboxTime) {
                delay = config.lightboxTime * 1000;
            }

            if (application.name === 'Shopping') {
               // jQuery.cookie.json = false;
                layoutComponent.on('afterShowContent', function afterShowContent(viewName) {
                    var viewLightBox;
                    if (!SC.isPageGenerator() && config.showLightbox === true) {
                        if (viewName !== 'newsletter-lightbox-view') {
                            viewLightBox = new NewsletterLightboxView({
                                model: new NewsletterModelSite(),
                                application: application
                            });

                            time = setTimeout(function afterTimeout() {
                                if (!Cookies.get('newsletterLightboxDisplayed')) {
                                    Cookies.set('newsletterLightboxDisplayed', 'true', {
                                        expires: 365,
                                        domain: domain,
                                        path: '/'
                                    });

                                    clearTime(time);
                                    viewLightBox.showInModal();
                                }
                            }, delay);
                        }
                    }
                });
            }

            layoutComponent.addToViewEventsDefinition(
                'Header.View',
                'click [data-action="showNewsletterModal"]',
                _.bind(openNewsletterModal, this, application)
            );
        }
    };
});

define('Newsletter.Lightbox.View', [
    'SC.Configuration',
    'Newsletter.View.Site',
    'newsletter_lightbox.tpl',
    'Session',
    'underscore',
    'Backbone'
], function NewsletterLightboxView(
    Configuration,
    NewsletterView,
    newsletterLightboxTpl,
    Session,
    _,
    Backbone
) {
    'use strict';

    return NewsletterView.extend({
        template: newsletterLightboxTpl,
        modalClass: 'modal-dialog-lg no-padding no-header',
        attributes: {
            'id': 'newsletter-lightbox-view',
            'class': 'view newsletter-lightbox-view'
        },
        newsletterSubscribe: function newsletterSubscribe(e) {
            var self = this;
            var promise;
            var errorCode;

            e.preventDefault();

            promise = this.saveForm(e);

            if (promise) {
                promise.fail(function afterSaveFormFailed(jqXhr) {
                    jqXhr.preventDefault = true;

                    if (jqXhr && jqXhr.responseJSON) {
                        errorCode = jqXhr.responseJSON.errorCode && (self.feedback[jqXhr.responseJSON.errorCode] ? jqXhr.responseJSON.errorCode : 'ERROR');
                    }

                    self.state.code = errorCode;
                    self.state.message = self.feedback[errorCode].message;
                    self.state.messageType = self.feedback[errorCode].type;
                }).done(function afterSavedForm() {
                    self.state.code = self.model.get('code');
                    self.state.message = self.feedback[self.model.get('code')].message;
                    self.state.messageType = self.feedback[self.model.get('code')].type;

                    // Backbone.history.navigate('newsletter-form', { trigger: true, replace: true });

                    // self.model.set('email', '');
                    // self.model.set('age', 'F');
                }).always(_.bind(self.render, self));
            }

            return promise;
        },
        destroy: function destroy() {
            var homeTouchpoint;
            Backbone.View.prototype.destroy.apply(this, arguments);
            if (this.model.get('email')) {
                if (this.options.application.name !== 'Shopping') {
                    homeTouchpoint = Session.get('touchpoints').home;
                    window.location.href = homeTouchpoint + '#newsletter-form?email=' + encodeURIComponent(this.model.get('email'));
                    return;
                }
                Backbone.history.navigate('#newsletter-form?email=' + encodeURIComponent(this.model.get('email')), {
                    trigger: true
                });
            }
        },
        getContext: function getContext() {
            var config = Configuration.newsletter;
            var image = config.lightboxImage || 'site/img/newsletter-lightbox.jpg';

            return {
                isFeedback: !!this.state.code,
                model: this.model,
                image: image,
                title: config.lightboxTitle || '',
                description: config.lightboxDescription || '',
                disclaimer: config.lightboxDisclaimer || ''
            };
        }
    });
});

define('Newsletter.Model.Site', [
    'Utils',
    'Backbone',
    'underscore'
], function NewsletterModelSite(
    Utils,
    Backbone,
    _
) {
    'use strict';

    function getAge(dateString) {
        var today = new Date();
        var birthDate = new Date(dateString);
        var age = today.getFullYear() - birthDate.getFullYear();
        var m = today.getMonth() - birthDate.getMonth();
        if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
            age--;
        }
        return age;
    }

    return Backbone.Model.extend({
        // @property {String} urlRoot
        urlRoot: Utils.getAbsoluteUrl('services/Newsletter.Service.ss'),

        // @property {String} email The email of the subscriber
        email: '',

        age: 'F',

        // @property validation Backbone.Validation attribute used for validating the form before submit.
        validation: {
            email: [
                {
                    required: true,
                    msg: 'Enter an email address to subscribe'
                },
                {
                    pattern: 'email',
                    msg: 'Valid email address is required'
                }
            ],
            age: {
                fn: function validateAge(value) {
                    if (value !== 'T') {
                        return _('You must be 13 years old or older.').translate();
                    }
                    return null;
                }
            },
            firstname: {
                required: true,
                msg: _('First Name is required').translate()
            },
            lastname: {
                required: true,
                msg: _('Last Name is required').translate()
            },
            birth: {
                /* eslint-disable */
                fn: function (value) {
                    var age;

                    if (!value) {
                        return _('Date of Birth is required').translate();
                    }

                    age = getAge(value);

                    if (isNaN(age)) {
                        return _('Date of Birth is invalid').translate();
                    } else if (age < 13) {
                        return _('You must be 13 years old or older.').translate();
                    }
                }
                /* eslint-enable */
            }
        }
    });
});

define('Newsletter.PageType', [
